#!/usr/bin/env node
/**
 * Numsy benchmark on synthetic data (no real contacts involved).
 *
 *   pnpm build && node scripts/benchmark.js            # 100k, 500k and 1M numbers
 *   node scripts/benchmark.js 250000                   # custom sizes
 *   node scripts/benchmark.js --md                     # Markdown table for the docs
 *
 * Every number is generated by a seeded PRNG in the same mixed formats real lists contain:
 * +91 / 0 prefixes, spaces and dashes, ~15% repeats, ~5% invalid and ~5% cells with two numbers.
 */
const os = require('node:os');
const { performance } = require('node:perf_hooks');
const {
  analyzeRows,
  checkNumber,
  extractNumbers,
  parseCsv,
  reportDataset,
  serializeDataset,
} = require('../dist/engine');

const args = process.argv.slice(2);
const markdown = args.includes('--md');
const sizes = args.filter((a) => /^\d+$/.test(a)).map(Number);
const SIZES = sizes.length ? sizes : [100_000, 500_000, 1_000_000];

function mulberry32(seed) {
  let a = seed;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function synthetic(count) {
  const random = mulberry32(42);
  const mobile = () =>
    `${6 + Math.floor(random() * 4)}${String(Math.floor(random() * 1e9)).padStart(9, '0')}`;
  const styles = [
    (n) => n,
    (n) => `+91 ${n.slice(0, 5)} ${n.slice(5)}`,
    (n) => `0${n}`,
    (n) => `${n.slice(0, 5)}-${n.slice(5)}`,
  ];
  const seen = [];
  const values = [];
  for (let i = 0; i < count; i++) {
    const roll = random();
    if (roll < 0.15 && seen.length) values.push(seen[Math.floor(random() * seen.length)]);
    else if (roll < 0.2) values.push(['9999999999', '12345', '5123456789'][i % 3]);
    else if (roll < 0.25) values.push(`${mobile()} / ${mobile()}`);
    else {
      const n = mobile();
      if (seen.length < 50_000) seen.push(n);
      values.push(styles[i % styles.length](n));
    }
  }
  return values;
}

const time = (fn) => {
  const started = performance.now();
  const result = fn();
  return { ms: performance.now() - started, result };
};

const rate = (count, ms) => `${Math.round(count / (ms / 1000)).toLocaleString('en-US')}/s`;
const sec = (ms) => (ms < 1000 ? `${Math.round(ms)} ms` : `${(ms / 1000).toFixed(2)} s`);

const results = [];
for (const size of SIZES) {
  const values = synthetic(size);
  const csv = `Name,Mobile\n${values.map((v, i) => `Contact ${i + 1},"${v}"`).join('\n')}\n`;

  // Warm up the JIT on a small slice so the first size isn't penalised
  for (const v of values.slice(0, 5000)) checkNumber(v);

  const validate = time(() => values.map((v) => checkNumber(v)));
  const extract = time(() => extractNumbers(values.slice(0, Math.min(size, 200_000)).join('\n')));
  const parse = time(() => parseCsv(csv));
  const analyze = time(() => analyzeRows(parse.result.data));
  const dedupe = time(() => analyzeRows(parse.result.data, { dedupe: 'first' }));
  const exportCsv = time(() =>
    serializeDataset(reportDataset(dedupe.result, { only: 'valid' }), 'csv'),
  );

  results.push({
    size,
    validate: validate.ms,
    extract: extract.ms,
    extractCount: Math.min(size, 200_000),
    parse: parse.ms,
    analyze: analyze.ms,
    dedupe: dedupe.ms,
    exportCsv: exportCsv.ms,
    valid: analyze.result.analytics.totalValidNumbers,
    unique: analyze.result.analytics.uniqueValidNumbers,
    csvMb: Buffer.byteLength(csv) / 1048576,
  });
}

const machine = `${os.cpus()[0]?.model?.trim() ?? 'unknown CPU'} · ${os.cpus().length} threads · ${Math.round(os.totalmem() / 1073741824)} GB · Node ${process.version} · ${os.platform()}`;

if (markdown) {
  console.log(`Measured on ${machine}.\n`);
  console.log('| Numbers | Validate | Parse CSV | Analyse | Analyse + de-dupe | Export CSV |');
  console.log('| ---: | ---: | ---: | ---: | ---: | ---: |');
  for (const r of results) {
    console.log(
      `| ${r.size.toLocaleString('en-US')} | ${sec(r.validate)} (${rate(r.size, r.validate)}) | ${sec(r.parse)} (${r.csvMb.toFixed(1)} MB) | ${sec(r.analyze)} | ${sec(r.dedupe)} | ${sec(r.exportCsv)} |`,
    );
  }
} else {
  console.log(machine);
  for (const r of results) {
    console.log(
      `${r.size.toLocaleString('en-US').padStart(9)} numbers  validate ${sec(r.validate).padStart(8)} (${rate(r.size, r.validate)})  ` +
        `extract ${sec(r.extract)} for ${r.extractCount.toLocaleString('en-US')}  parse ${sec(r.parse)} (${r.csvMb.toFixed(1)} MB)  ` +
        `analyse ${sec(r.analyze)}  de-dupe ${sec(r.dedupe)}  export ${sec(r.exportCsv)}  ` +
        `→ ${r.valid.toLocaleString('en-US')} valid, ${r.unique.toLocaleString('en-US')} unique`,
    );
  }
}
